/**
 * Register the managed ZCode proxy as a 9router-go custom provider.
 *
 * The gateway models every third-party OpenAI-compatible endpoint as a
 * provider NODE (`openai-compatible-<apiType>-<uuid>`) plus a CONNECTION that
 * carries the credential and marks the node active. Both dashboard routes
 * accept the local CLI token, so this needs no password interaction.
 *
 * Node ids are generated by the gateway, so registration is made idempotent by
 * looking up the node by its unique name first; a repeated plugin reload
 * therefore repoints the existing node instead of accumulating duplicates.
 * @module dsh-9router-go/zcode-provision
 */

import { CLI_TOKEN_HEADER } from './provision.mjs'

/** Gateway node type for an OpenAI-compatible upstream. */
const NODE_TYPE = 'openai-compatible'

/** Gateway API dialect the proxy speaks on `/v1/chat/completions`. */
const API_TYPE = 'chat'

async function readJson(response, what) {
  if (!response.ok) throw new Error(`${what} failed: HTTP ${response.status}`)
  try {
    return await response.json()
  } catch (error) {
    throw new Error(`${what} returned invalid JSON: ${error.message}`)
  }
}

/**
 * Create or repoint the provider node for the ZCode proxy.
 * @param options - gateway endpoint, CLI token, node facts, fetcher, deadline.
 * @returns the node id and whether it was created by this call.
 * @throws when the gateway refuses the write or answers with no node id.
 */
export async function ensureProviderNode({
  endpoint, token, name, prefix, baseUrl, fetcher = fetch, timeoutMs = 10000,
}) {
  const headers = { [CLI_TOKEN_HEADER]: token }
  const listed = await fetcher(`${endpoint}/api/provider-nodes`, {
    headers,
    signal: AbortSignal.timeout(timeoutMs),
  })
  const body = await readJson(listed, 'listing gateway provider nodes')
  const existing = (Array.isArray(body?.nodes) ? body.nodes : []).find(node => node?.name === name)
  if (existing?.id !== undefined) {
    const response = await fetcher(`${endpoint}/api/provider-nodes/${encodeURIComponent(existing.id)}`, {
      method: 'PUT',
      headers: { ...headers, 'content-type': 'application/json' },
      body: JSON.stringify({ name, prefix, apiType: API_TYPE, baseUrl, type: NODE_TYPE }),
      signal: AbortSignal.timeout(timeoutMs),
    })
    await readJson(response, 'updating the gateway provider node')
    return { id: existing.id, created: false }
  }
  const created = await fetcher(`${endpoint}/api/provider-nodes`, {
    method: 'POST',
    headers: { ...headers, 'content-type': 'application/json' },
    body: JSON.stringify({ name, prefix, apiType: API_TYPE, baseUrl, type: NODE_TYPE }),
    signal: AbortSignal.timeout(timeoutMs),
  })
  const node = await readJson(created, 'creating a gateway provider node')
  const id = node?.node?.id ?? node?.id
  if (typeof id !== 'string' || id.length === 0) {
    throw new Error('gateway node creation returned no node id')
  }
  return { id, created: true }
}

/**
 * Create or update the active connection that authenticates the node.
 *
 * The two gateway routes take the credential differently, which is a real trap:
 * the create route reads a top-level `apiKey`, while the update route reads the
 * merged `data` map and ignores `apiKey` at the top level entirely. Sending only
 * the top-level field on update therefore reports success while leaving the old
 * credential in place, so the update payload carries both forms.
 * @param options - gateway endpoint, CLI token, node id, credential, fetcher, deadline.
 * @returns the connection id.
 * @throws when the gateway refuses the write or answers with no connection id.
 */
export async function ensureProviderConnection({
  endpoint, token, provider, apiKey, defaultModel, name, fetcher = fetch, timeoutMs = 10000,
}) {
  const headers = { [CLI_TOKEN_HEADER]: token }
  const listed = await fetcher(`${endpoint}/api/connections`, {
    headers,
    signal: AbortSignal.timeout(timeoutMs),
  })
  const connections = await readJson(listed, 'listing gateway connections')
  const existing = (Array.isArray(connections) ? connections : [])
    .find(connection => connection?.provider === provider)
  const providerSpecificData = { prefix: name }
  if (existing?.id !== undefined) {
    const response = await fetcher(`${endpoint}/api/connections/${encodeURIComponent(existing.id)}`, {
      method: 'PUT',
      headers: { ...headers, 'content-type': 'application/json' },
      body: JSON.stringify({
        name,
        isActive: true,
        defaultModel,
        providerSpecificData,
        data: { apiKey, defaultModel, providerSpecificData },
      }),
      signal: AbortSignal.timeout(timeoutMs),
    })
    await readJson(response, 'updating the gateway connection')
    return { id: existing.id, created: false }
  }
  const created = await fetcher(`${endpoint}/api/connections`, {
    method: 'POST',
    headers: { ...headers, 'content-type': 'application/json' },
    body: JSON.stringify({
      provider,
      authType: 'compatible',
      name,
      apiKey,
      isActive: 1,
      defaultModel,
      providerSpecificData,
    }),
    signal: AbortSignal.timeout(timeoutMs),
  })
  const body = await readJson(created, 'creating a gateway connection')
  const id = body?.id ?? body?.connection?.id
  if (typeof id !== 'string' || id.length === 0) {
    throw new Error('gateway connection creation returned no connection id')
  }
  return { id, created: true }
}

/**
 * Register the proxy node, its connection, and the models it serves.
 *
 * The model registration is not optional: the gateway lists traffic-ready
 * custom models from its own store and does not probe a custom node's
 * `/v1/models`, so a node with no registered model stays invisible to
 * `?connected=1` clients even though its connection is active.
 * @param options - gateway facts, proxy facts, fetcher, and logger.
 * @returns the node id, connection id, and the models registered.
 * @throws when a gateway write fails, so the failure reaches the logger rather
 *   than leaving a half-registered provider behind.
 */
export async function registerZcodeProvider({
  endpoint, token, proxyEndpoint, apiKey, prefix, models, routeName, fetcher = fetch, log = console,
}) {
  const node = await ensureProviderNode({
    endpoint, token, name: routeName, prefix, baseUrl: `${proxyEndpoint}/v1`, fetcher,
  })
  const connection = await ensureProviderConnection({
    endpoint, token, provider: node.id, apiKey, defaultModel: models[0], name: prefix, fetcher,
  })
  for (const model of models) {
    const response = await fetcher(`${endpoint}/api/models/custom`, {
      method: 'POST',
      headers: { [CLI_TOKEN_HEADER]: token, 'content-type': 'application/json' },
      body: JSON.stringify({ id: model, providerAlias: node.id, type: 'llm' }),
      signal: AbortSignal.timeout(10000),
    })
    await readJson(response, `registering model ${model}`)
  }
  const verb = node.created ? 'registered' : 'updated'
  log.info?.(`zcode: ${verb} 9router-go provider "${routeName}" with ${models.length} model(s)`)
  return { nodeId: node.id, connectionId: connection.id, created: node.created, models }
}

/**
 * Read the model ids the gateway serves through one provider prefix.
 *
 * The `?connected=1` catalog is filtered by prefix so this reports only the
 * ZCode route; a gateway that lists nothing yet is a real failure worth
 * surfacing, because the provider would otherwise be advertised as empty.
 * @param options - gateway endpoint, API key, prefix filter, fetcher, deadline.
 * @returns distinct model ids, most-capable first as the gateway orders them.
 * @throws when the catalog request fails or carries no matching model.
 */
export async function zcodeModelIds({
  endpoint, key, prefix, maxModels, fetcher = fetch, timeoutMs = 15000,
}) {
  const response = await fetcher(`${endpoint}/v1/models?connected=1`, {
    headers: { Authorization: `Bearer ${key}` },
    signal: AbortSignal.timeout(timeoutMs),
  })
  const body = await readJson(response, 'reading the gateway model catalog')
  const ids = [...new Set((Array.isArray(body?.data) ? body.data : [])
    .map(entry => entry?.id)
    .filter(id => typeof id === 'string' && id.startsWith(`${prefix}/`)))]
  if (ids.length === 0) {
    throw new Error(`gateway reported no model under the "${prefix}/" prefix; the ZCode node may still be activating`)
  }
  return ids.slice(0, maxModels)
}
